const fs = require('node:fs');
const out = fs.createWriteStream('/tmp/dd-bp-demo.txt');

function writeLots(i = 0) {
  let ok = true;
  while (i < 10000 && ok) {
    ok = out.write(`line ${i}\n`); // false => buffer past highWaterMark
    i++;
  }
  if (i < 10000) out.once('drain', () => writeLots(i)); // resume when drained
  else out.end(() => console.log('done writing with backpressure'));
}
